#!/usr/bin/env python3
"""Consolidate recorded unfinished enemy work without promoting acceptance."""
import collections,datetime,hashlib,html,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'docs/reports/isaac-enemy-missing-work';OUT.mkdir(exist_ok=True)
source=ROOT/'docs/research/isaac-enemy-port-status.json';status=json.loads(source.read_text());records=status['records'];e=html.escape
rows=[dict(id=r['id'],name=r['name'],review=r['review'],disposition=r['disposition'],implementation=r['implementation'],remaining=r.get('unresolved',[]),contract_unknowns=(r.get('contract') or {}).get('unknowns'),runtime=r.get('runtime',[])) for r in records]
counts=dict(total_records=len(records),regular_enemies=sum(r['disposition']=='ordinary' for r in records),fully_accepted=sum(r['implementation']=='complete' for r in records),implementations=dict(collections.Counter(r['implementation'] for r in records)),dispositions=dict(collections.Counter(r['disposition'] for r in records)))
priorities=[
 dict(title='Finish champion coverage on the earlier basic enemies',status='Partially implemented',detail='Frowning Gaper10.0, Gaper10.1, Pacer11.1 and Horf12.0allow8of26combat types. Gusher11.0allows9, including Magenta. Reuse the existing handlers and verify each body/modifier interaction. The five Chargers and ordinary SubHorf812.0already allow all26with scoped tests; their shared loot/source-fidelity gaps remain.',evidence='../isaac-enemy-port/interaction-gaps/index.html'),
 dict(title='Champion rewards and native selection weights',status='Missing or deliberately adapted',detail='Isaac-specific hearts, batteries, pills, chests and other champion reward mappings are not ported wholesale. Existing ordinary DeathWard loot remains. Champion type selection is uniform over stage-eligible types rather than native rarity weights. Implement the required resources or explicitly select and document DeathWard equivalents.',evidence='../isaac-enemy-port/sub-horf/champions/index.html'),
 dict(title='Connect actual item pickups to enemy statuses',status='Missing end to end',detail='The enemy-side API supports Fear, Confusion, Freeze, Slow, Poison, Burn, Shrink and Charm for reviewed recipients. The ordinary item dispatcher does not yet grant these status effects on hits. Add item triggers, proc rules, duration/strength/stacking and ownership. API/debug tests alone do not make these playable item perks.',evidence='../isaac-enemy-port/interaction-gaps/index.html'),
 dict(title='Complete the applicable combined-effect matrix',status='Selected combinations tested',detail='Existing weapon pairs, Charm/morph/follower cases and SubHorf champion/death combinations have scoped tests. Remaining work is a finite, explicit per-body list covering applicable build, status and champion combinations, ownership through birth/morph/death, room/floor travel, save/load and queue pressure. Do not describe every untested combination as missing code, or existing generic handlers as fully accepted.',evidence='../isaac-enemy-port/sub-horf/champions/status.json'),
 dict(title='Resolve source-specific behavior exceptions',status='Open per actor',detail='The roster below preserves individual unknowns. Examples include special champion knockback/status/item rules, stationary creep behavior on earlier Horf variants, exact ordinary SubHorf death-projectile packet/direction and source water-stream behavior. Current local conversions and adaptations must remain separate from native numbers.',evidence='../isaac-enemy-port/sub-horf/status.json'),
 dict(title='Classify and port the remaining source records in small batches',status='Incomplete source inventory',detail='418records have status missing and18have existing_unverified. These counts include bosses, hazards and components as well as enemies; they are not counts of missing regular enemies. Another205records are in_progress. Tainted SubHorf812.1is still missing. Classification, dependencies, stage eligibility and actor-specific tests must precede acceptance.',evidence='../regular-enemy-implementation.html'),
 dict(title='Finish visual, balance and performance acceptance',status='Partial evidence',detail='155reviewed regular enemies have runtime definitions, but none has full acceptance. Finish mixed-room/terrain/occlusion readability, all relevant animation states, human starting-kit/build balance and controlled rendered performance. Isolated captures and headless timing tests do not establish these. WASM verification is waived by user instruction and is not an outstanding requirement.',evidence='../regular-enemy-implementation.html')]
completed=['Source base/stage HP profiles and shared regular-health scaling are verified for155reviewed regular actors; default multiplier remains1. Player defaults remain100HP/24damage.','Ordinary SubHorf812.0is implemented with reactive spin/fire, owned final shot and exact1/60Horf substitution.','All26SubHorf combat champion types have scoped stat/Charm and death-affiliation checks; native resident-stage gates and production tuning are retained.','The current SubHorf champion checkpoint has six passing affected native suites across its recorded batch/retry, a passing native build and three inspected representative captures.']
report=dict(generated_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),scope='Recorded enemy-port work remaining at commit preparation. This is not a newly completed full audit of every source interaction.',source=str(source.relative_to(ROOT)),source_sha256=hashlib.sha256(source.read_bytes()).hexdigest(),counts=counts,completed_checkpoint=completed,priorities=priorities,records=rows,waived='WASM validation, explicitly waived by user',acceptance='in_progress means partially implemented, with recorded gaps; it never means fully accepted.')
(OUT/'status.json').write_text(json.dumps(report,indent=2)+'\n')
ul=lambda values:'<ul>'+''.join('<li>'+e(v)+'</li>' for v in values)+'</ul>'
body='<p><strong>155reviewed regular actors have runtime definitions. None has full acceptance.</strong> The complete653-record source inventory also includes bosses, hazards and component identities.</p><p>Snapshot: '+e(report['generated_utc'])+'. Recorded status is evidence of the current scope, not a fresh exhaustive audit of every enemy/item interaction.</p><div class="metrics">'+''.join('<div><b>'+str(n)+'</b><span>'+e(label)+'</span></div>' for label,n in [('Regular actors',counts['regular_enemies']),('Partially implemented source records',counts['implementations'].get('in_progress',0)),('Missing source records',counts['implementations'].get('missing',0)),('Existing but unverified records',counts['implementations'].get('existing_unverified',0)),('Fully accepted',counts['fully_accepted'])])+'</div><h2>Completed checkpoint</h2>'+ul(completed)+'<h2>Remaining work</h2>'
for i,p in enumerate(priorities,1):body+='<h3>'+str(i)+'. '+e(p['title'])+'</h3><p><strong>'+e(p['status'])+'.</strong> '+e(p['detail'])+' <a href="'+p['evidence']+'">Evidence and detail</a>.</p>'
body+='<h2>Recorded per-actor gaps</h2><p>Default view shows the155reviewed regular actors. Select the full inventory to inspect missing/unclassified records; excluded records are retained with their disposition.</p><div class="controls"><label>Scope <select id="scope"><option value="regular">Reviewed regular actors</option><option value="all">Full source inventory</option><option value="missing">Missing definitions</option><option value="unverified">Existing but unverified</option></select></label><input id="search" aria-label="Search actors" placeholder="Search name, ID or gap"><span id="count"></span></div><div id="roster"></div><p><a href="status.json">Machine-readable report with every recorded gap</a> · <a href="../regular-enemy-implementation.html">Full implementation report</a> · <a href="../isaac-enemy-port/sub-horf/champions/index.html">Latest champion checkpoint</a></p><p>Rebuild with scripts/isaac-reference/build-enemy-missing-work-report.py. Local preserved source archives remain separately documented under reference/README.md.</p>'
data=json.dumps(rows,separators=(',',':')).replace('<','\u003c')
script='''const rows=DATA;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function draw(){const mode=document.querySelector('#scope').value,q=document.querySelector('#search').value.toLowerCase();const shown=rows.filter(r=>(mode==='all'||mode==='regular'&&r.disposition==='ordinary'||mode==='missing'&&r.implementation==='missing'||mode==='unverified'&&r.implementation==='existing_unverified')&&JSON.stringify(r).toLowerCase().includes(q));document.querySelector('#count').textContent=shown.length+' records';document.querySelector('#roster').innerHTML=shown.map(r=>'<details><summary>'+esc(r.name)+' <small>'+esc(r.id)+' · '+esc(r.disposition)+' · '+esc(r.implementation)+'</small></summary>'+((r.remaining.length)?'<ul>'+r.remaining.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'<p>No additional per-record gap was itemized; this does not certify completion.</p>')+(r.contract_unknowns?'<p><strong>Recorded unknowns:</strong> '+esc(r.contract_unknowns)+'</p>':'')+'</details>').join('')}document.querySelector('#scope').addEventListener('change',draw);document.querySelector('#search').addEventListener('input',draw);draw();'''.replace('DATA',data,1)
(OUT/'index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DeathWard enemy work remaining</title><style>body{max-width:1100px;margin:36px auto;padding:0 18px;background:#182024;color:#eee5d7;font:17px/1.6 system-ui}a{color:#8fd5ce}h1,h2,h3{line-height:1.3}li{margin:9px 0}.metrics{display:flex;flex-wrap:wrap;gap:12px}.metrics div{flex:1 1 150px;background:#263238;padding:16px}.metrics b{font-size:32px;display:block}.metrics span{display:block}small{color:#b1c6c4}details{padding:12px 0;border-bottom:1px solid #596364}summary{cursor:pointer;overflow-wrap:anywhere}p,li{overflow-wrap:anywhere}.controls{display:flex;flex-wrap:wrap;gap:12px;align-items:center}input,select{max-width:100%;padding:8px;font:inherit}#search{flex:1 1 220px;min-width:0}#count{white-space:nowrap}</style><h1>Enemy implementation: work remaining</h1>'+body+'<script>'+script+'</script></html>')
print(json.dumps(dict(report=str((OUT/'index.html').relative_to(ROOT)),counts=counts)))
